// RunJSONSerializationTestForWorkspacesFeaturesetsVersion_STATUS runs a test to see if a specific instance of WorkspacesFeaturesetsVersion_STATUS round trips to JSON and back losslessly
func RunJSONSerializationTestForWorkspacesFeaturesetsVersion_STATUS(subject WorkspacesFeaturesetsVersion_STATUS) string {
	// Serialize to JSON
	bin, err := json.Marshal(subject)
	if err != nil {
		return err.Error()
	}

	// Deserialize back into memory
	var actual WorkspacesFeaturesetsVersion_STATUS
	err = json.Unmarshal(bin, &actual)
	if err != nil {
		return err.Error()
	}

	// Check for outcome
	match := cmp.Equal(subject, actual, cmpopts.EquateEmpty())
	if !match {
		actualFmt := pretty.Sprint(actual)
		subjectFmt := pretty.Sprint(subject)
		result := diff.Diff(subjectFmt, actualFmt)
		return result
	}

	return ""
}

